1	import { useMemo, useState } from "react";
2	import { useLocation } from "wouter";
3	import { useNotifications } from "@/components/notification-system";
4	import { usePropertyInvoices, usePropertySchedules, usePropertyTenants } from "@/lib/property-data";
5	import {
6	  type Timeframe,
7	  buildBuckets,
8	  periodWindow,
9	  collectedCents,
10	  growthPct,
11	  filterByProperty,
12	} from "@/lib/property-dashboard-data";
13	import { fmtNZD } from "@/lib/report-utils";
14	import {
15	  DesktopPageScaffold,
16	  type DesktopRoutePageProps,
17	} from "../DesktopPageScaffold";
18	
19	/* ── palette ── */
20	const ACCENT = "#5E9EFF";
21	const ACCENT_SOFT = "#7FB2FF";
22	const NAV_DIM = "#4A86F0";
23	const ACTIVE = "#66A9FF";
24	const TEXT_SOFT = "#F4F6FF";
25	const NAVY = "#000F3F";
26	const CHIP = "#0F1747";
27	const BAR_DIM = "rgba(94,158,255,0.32)";
28	const GREEN = "#35D07F";
29	const RED = "#F0656C";
30	const AMBER = "#F0A34E";
31	
32	const RANGES: Timeframe[] = ["day", "week", "month", "year"];
33	const RANGE_UNIT: Record<Timeframe, string> = {
34	  day: "hour",
35	  week: "day",
36	  month: "week",
37	  year: "month",
38	};
39	
40	const fmtDollars = (cents: number) => "$" + Math.round(cents / 100).toLocaleString("en-NZ");
41	
42	function initials(name: string): string {
43	  const parts = String(name ?? "")
44	    .trim()
45	    .split(/\s+/)
46	    .filter((p) => /^[a-z0-9]/i.test(p));
47	  if (parts.length === 0) return "–";
48	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
49	  return (parts[0][0] + parts[1][0]).toUpperCase();
50	}
51	
52	/* Rent invoices carry integer cents and a `dueAt`; tenants carry first/last name. */
53	const amountOf = (invoice: any) => invoice?.amountCents ?? 0;
54	const dueDateOf = (invoice: any) => invoice?.dueAt ?? invoice?.createdAt;
55	const tenantFullName = (t: any) =>
56	  `${t?.firstName ?? ""} ${t?.lastName ?? ""}`.trim() || "tenant";
57	
58	const shortDate = (v: unknown) => {
59	  if (!v) return "—";
60	  const d = new Date(String(v));
61	  return isNaN(d.getTime())
62	    ? "—"
63	    : d.toLocaleDateString("en-NZ", { day: "numeric", month: "short" }).toLowerCase();
64	};
65	
66	interface HealthStat {
67	  k: string;
68	  v: string;
69	  n: string;
70	  label: string;
71	  col: string;
72	}
73	interface DetailRow {
74	  name: string;
75	  sub: string;
76	  amt: string;
77	  col: string;
78	}
79	
80	/* Portfolio figures, chart buckets and the health strip — all derived from the
81	   shared property cache so the desktop and mobile dashboards can never
82	   disagree about a number. */
83	function usePropertyHomeModel(tf: Timeframe, selBar: number, propFilter: string | null) {
84	  const tenantsQuery = usePropertyTenants();
85	  const invoicesQuery = usePropertyInvoices();
86	  const schedulesQuery = usePropertySchedules();
87	
88	  const tenants = tenantsQuery.data ?? [];
89	  const invoices = invoicesQuery.data ?? [];
90	  const schedules = schedulesQuery.data ?? [];
91	
92	  return useMemo(() => {
93	    const { invoices: fInv, tenants: fTen } = filterByProperty(invoices, tenants, propFilter);
94	
95	    const win = periodWindow(tf);
96	    const total = collectedCents(fInv, win.start, win.end);
97	    const growth = growthPct(total, collectedCents(fInv, win.prevStart, win.prevEnd));
98	
99	    const buckets = buildBuckets(fInv, tf);
100	    const chartTotal = buckets.reduce((a, b) => a + b.valueCents, 0);
101	    const max = Math.max(...buckets.map((b) => b.valueCents), 1);
102	    let peak = 0;
103	    buckets.forEach((b, i) => {
104	      if (b.valueCents > buckets[peak].valueCents) peak = i;
105	    });
106	    const selectedIdx = selBar >= 0 && selBar < buckets.length ? selBar : peak;
107	    const selected = buckets[selectedIdx];
108	
109	    /* Portfolio health: what needs the landlord's attention right now. */
110	    const failed = fInv.filter((i: any) => i.status === "failed");
111	    const overdue = fInv.filter((i: any) => i.status === "overdue");
112	    const weekEnd = new Date();
113	    weekEnd.setDate(weekEnd.getDate() + 7);
114	    const now = new Date();
115	    const dueSoon = fInv.filter((i: any) => {
116	      if (i.status === "paid" || i.status === "paid_external" || i.status === "voided") return false;
117	      const due = new Date(dueDateOf(i));
118	      return !isNaN(due.getTime()) && due >= now && due <= weekEnd;
119	    });
120	
121	    const sum = (rows: any[]) => rows.reduce((s, i) => s + amountOf(i), 0);
122	    const tenantName = (invoice: any) => {
123	      const t = fTen.find((x: any) => x.id === invoice.tenantProfileId);
124	      return t ? tenantFullName(t) : "tenant";
125	    };
126	    const tenantAddress = (invoice: any) => {
127	      const t = fTen.find((x: any) => x.id === invoice.tenantProfileId);
128	      return t?.propertyAddress || invoice.propertyAddress || "";
129	    };
130	
131	    const health: HealthStat[] = [
132	      { k: "failed", v: fmtDollars(sum(failed)), n: String(failed.length), label: "failed", col: failed.length ? RED : TEXT_SOFT },
133	      { k: "overdue", v: fmtDollars(sum(overdue)), n: String(overdue.length), label: "overdue", col: overdue.length ? AMBER : TEXT_SOFT },
134	      { k: "due", v: fmtDollars(sum(dueSoon)), n: String(dueSoon.length), label: "due this week", col: TEXT_SOFT },
135	    ];
136	
137	    const toRows = (rows: any[], col: string): DetailRow[] =>
138	      rows.slice(0, 8).map((i: any) => ({
139	        name: tenantName(i),
140	        sub: `${tenantAddress(i) || "no address"} · ${shortDate(dueDateOf(i))}`,
141	        amt: fmtNZD(amountOf(i)),
142	        col,
143	      }));
144	
145	    const detail: Record<string, { title: string; rows: DetailRow[] }> = {
146	      failed: { title: "FAILED — RETRY OR RE-SEND", rows: toRows(failed, RED) },
147	      overdue: { title: "OVERDUE — CHASE THESE", rows: toRows(overdue, AMBER) },
148	      due: { title: "DUE IN THE NEXT 7 DAYS", rows: toRows(dueSoon, TEXT_SOFT) },
149	    };
150	
151	    /* Tenant list with each tenant's next unpaid invoice. */
152	    const recentTenants = fTen
153	      .filter((t: any) => t.status !== "archived")
154	      .map((t: any) => {
155	        const open = fInv
156	          .filter(
157	            (i: any) =>
158	              i.tenantProfileId === t.id &&
159	              i.status !== "paid" &&
160	              i.status !== "paid_external" &&
161	              i.status !== "voided",
162	          )
163	          .sort(
164	            (a: any, b: any) =>
165	              new Date(dueDateOf(a)).getTime() - new Date(dueDateOf(b)).getTime(),
166	          );
167	        const next = open[0];
168	        const schedule = schedules.find((s: any) => s.tenantProfileId === t.id);
169	        return {
170	          id: t.id,
171	          name: tenantFullName(t),
172	          address: t.propertyAddress || "no address",
173	          amt: next
174	            ? fmtNZD(amountOf(next))
175	            : schedule
176	              ? fmtNZD(schedule.amountCents ?? 0)
177	              : "—",
178	          due: next ? shortDate(dueDateOf(next)) : schedule ? "scheduled" : "nothing due",
179	          sortKey: next ? new Date(dueDateOf(next)).getTime() : Number.MAX_SAFE_INTEGER,
180	        };
181	      })
182	      .sort((a, b) => a.sortKey - b.sortKey);
183	
184	    const addresses = Array.from(
185	      new Set(tenants.map((t: any) => t.propertyAddress).filter(Boolean)),
186	    ) as string[];
187	
188	    return {
189	      total,
190	      growth,
191	      buckets,
192	      chartTotal,
193	      max,
194	      peak,
195	      selectedIdx,
196	      selected,
197	      health,
198	      detail,
199	      tenants: recentTenants,
200	      addresses,
201	      activeTenants: fTen.filter((t: any) => t.status !== "archived").length,
202	      isLoading: invoicesQuery.isLoading || tenantsQuery.isLoading,
203	      isError: invoicesQuery.isError || tenantsQuery.isError,
204	      refetch: () => {
205	        invoicesQuery.refetch();
206	        tenantsQuery.refetch();
207	      },
208	    };
209	  }, [invoices, tenants, schedules, tf, selBar, propFilter, invoicesQuery.isLoading, invoicesQuery.isError, tenantsQuery.isLoading, tenantsQuery.isError]);
210	}
