.ph-action-glow { position:absolute; left:-22%; top:-58%; width:144%; height:216%; border-radius:50%; background:radial-gradient(closest-side,rgba(102,169,255,0.18),transparent 70%); animation:glowDrift 11s ease-in-out infinite; pointer-events:none; }
.ph-action-primary .ph-action-glow { background:radial-gradient(closest-side,rgba(255,255,255,0.22),transparent 70%); }
.ph-action-ico { position:absolute; top:12px; right:12px; }
.ph-action-label { position:absolute; left:14px; bottom:12px; font-weight:500; font-size:13.5px; line-height:1.25; color:#E8F0FF; }

.ph-empty { display:flex; align-items:center; justify-content:center; flex:1; min-height:64px; font-weight:300; font-size:12.5px; color:rgba(191,209,255,0.5); }
`;

content.content:
1	import { useMemo, useState } from "react";
2	import { useMutation, useQueryClient } from "@tanstack/react-query";
3	import { usePropertyInvoices, usePropertyTenants, PROPERTY_KEYS } from "@/lib/property-data";
4	import { propHeaders } from "@/lib/property-api";
5	import { fmtNZD } from "@/lib/report-utils";
6	import {
7	  DesktopPageScaffold,
8	  type DesktopRoutePageProps,
9	} from "../DesktopPageScaffold";
10	import { DesktopDirectoryProfile } from "../DesktopDirectoryProfile";
11	
12	/* ── palette ── */
13	const ACCENT = "#5E9EFF";
14	const ACCENT_SOFT = "#7FB2FF";
15	const NAV_DIM = "#4A86F0";
16	const ACTIVE = "#66A9FF";
17	const TEXT_SOFT = "#F4F6FF";
18	const NAVY = "#000F3F";
19	const RED = "#F0656C";
20	const AMBER = "#F0A34E";
21	
22	type Channel = "email" | "whatsapp" | "sms";
23	
24	const CHANNELS: { v: Channel; label: string }[] = [
25	  { v: "email", label: "email" },
26	  { v: "sms", label: "sms" },
27	  { v: "whatsapp", label: "whatsapp" },
28	];
29	
30	const initialsOf = (t: any) =>
31	  `${t?.firstName?.[0] ?? ""}${t?.lastName?.[0] ?? ""}`.toUpperCase() || "?";
32	
33	const fullNameOf = (t: any) => `${t?.firstName ?? ""} ${t?.lastName ?? ""}`.trim() || "tenant";
34	
35	const fmtDue = (invoice: any) =>
36	  invoice?.dueAt
37	    ? new Date(invoice.dueAt).toLocaleDateString("en-NZ", { day: "2-digit", month: "2-digit" })
38	    : "";
39	
40	const EMPTY_FORM = {
41	  firstName: "",
42	  lastName: "",
43	  email: "",
44	  phone: "",
45	  propertyAddress: "",
46	  preferredChannel: "email" as Channel,
47	};
48	
49	export default function DesktopPropertyClients(props: DesktopRoutePageProps) {
50	  const queryClient = useQueryClient();
51	  const [selectedTenantId, setSelectedTenantId] = useState<string | null>(() => typeof window === "undefined" ? null : new URLSearchParams(window.location.search).get("client"));
52	  const [search, setSearch] = useState("");
53	  const [propFilter, setPropFilter] = useState<string | null>(null);
54	  const [scopeOpen, setScopeOpen] = useState(false);
55	  const [addOpen, setAddOpen] = useState(false);
56	  const [form, setForm] = useState(EMPTY_FORM);
57	  const [saveError, setSaveError] = useState<string | null>(null);
58	
59	  const tenantsQuery = usePropertyTenants();
60	  const invoicesQuery = usePropertyInvoices();
61	  const tenants = tenantsQuery.data ?? [];
62	  const invoices = invoicesQuery.data ?? [];
63	
64	  /* Same worst-case-status rule the mobile directory uses, so a tenant reads the
65	     same on both UIs: overdue beats pending, pending beats the newest invoice. */
66	  const invoiceByTenant = useMemo(() => {
67	    const map = new Map<string, any>();
68	    for (const t of tenants) {
69	      const live = invoices.filter((i: any) => i.tenantProfileId === t.id && i.status !== "voided");
70	      if (live.length === 0) continue;
71	      const overdue = live.find((i: any) => i.status === "overdue");
72	      const pending = live.find((i: any) =>
73	        ["dispatched", "pending_dispatch", "dispatch_failed"].includes(i.status),
74	      );
75	      map.set(
76	        t.id,
77	        overdue ??
78	          pending ??
79	          [...live].sort(
80	            (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
81	          )[0],
82	      );
83	    }
84	    return map;
85	  }, [tenants, invoices]);
86	
87	  const activeTenants = useMemo(
88	    () => tenants.filter((t: any) => t.status !== "archived"),
89	    [tenants],
90	  );
91	  const addresses = useMemo(
92	    () =>
93	      Array.from(
94	        new Set(activeTenants.map((t: any) => t.propertyAddress).filter(Boolean)),
95	      ) as string[],
96	    [activeTenants],
97	  );
98	  /* A property can disappear from the active choices after a refetch (for
99	     example, when its final tenant is archived). Treat that stale selection as
100	     all properties immediately instead of leaving the directory at an
101	     impossible zero-row scope. */
102	  const propertyScope =
103	    propFilter && addresses.includes(propFilter) ? propFilter : null;
104	
105	  /* The count sits under the scope pill, so it answers "how many here": it
106	     follows the property scope but not the search box, which is a find-tool
107	     rather than a filter. Same rule as the trades directory (3b). */
108	  const scopedTenants = activeTenants.filter(
109	    (t: any) => !propertyScope || t.propertyAddress === propertyScope,
110	  );
111	
112	  const term = search.trim().toLowerCase();
113	  const rows = scopedTenants.filter(
114	    (t: any) =>
115	      !term ||
116	      fullNameOf(t).toLowerCase().includes(term) ||
117	      String(t.propertyAddress ?? "").toLowerCase().includes(term),
118	  );
119	  const selectedTenant = tenants.find((tenant: any) => tenant.id === selectedTenantId) ?? null;
120	  const selectTenant = (id: string) => {
121	    setSelectedTenantId(id);
122	    const url = new URL(window.location.href);
123	    url.searchParams.set("client", id);
124	    window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
125	  };
126	
127	  const createMutation = useMutation({
128	    mutationFn: async (data: typeof EMPTY_FORM) => {
129	      const res = await fetch("/api/property/tenants", {
130	        method: "POST",
131	        headers: { "Content-Type": "application/json", ...propHeaders() },
132	        body: JSON.stringify(data),
133	      });
134	      if (!res.ok) {
135	        const message = await res
136	          .json()
137	          .then((d) => d.message)
138	          .catch(() => `Error ${res.status}`);
139	        throw new Error(message);
140	      }
141	      return res.json();
142	    },
143	    onSuccess: () => {
144	      queryClient.invalidateQueries({ queryKey: PROPERTY_KEYS.tenants as any });
145	      setAddOpen(false);
146	      setForm(EMPTY_FORM);
147	      setSaveError(null);
148	    },
149	    onError: (err: any) => setSaveError(err?.message || "Failed to add tenant."),
150	  });
151	
152	  /* The chosen delivery channel must have a contact to send to — the mobile
153	     form's rule, kept identical so the same tenants are valid on both. */
154	  const channelContactOk =
155	    form.preferredChannel === "email" ? !!form.email.trim() : !!form.phone.trim();
156	  const formValid =
157	    !!form.firstName.trim() && !!form.lastName.trim() && !!form.propertyAddress.trim() && channelContactOk;
158	
159	  const set = (k: keyof typeof EMPTY_FORM) => (v: string) =>
160	    setForm((f) => ({ ...f, [k]: v } as typeof EMPTY_FORM));
161	
162	  const countLabel = `active tenant${scopedTenants.length === 1 ? "" : "s"}`;
163	  const countAnnouncement = tenantsQuery.isLoading
164	    ? "loading active tenants"
165	    : `${scopedTenants.length} ${countLabel}`;
166	
167	  return (
168	    <DesktopPageScaffold {...props} vertical="property" page="directory" showScope={false}>
169	      <style>{PC_CSS}</style>
170	      <div className="pc-body">
171	        <div className="pc-scope-wrap">
172	          <button
173	            type="button"
174	            className="pc-scope"
175	            aria-haspopup="listbox"
176	            aria-expanded={scopeOpen}
177	            aria-label={`${propertyScope ?? "all properties"} scope`}
178	            onClick={() => setScopeOpen((o) => !o)}
179	          >
180	            <span>{propertyScope ?? "all properties"}</span>
181	            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
182	          </button>
183	          {scopeOpen && (
184	            <div className="pc-scope-menu" role="listbox">
185	              <button
186	                type="button"
187	                className="pc-scope-opt"
188	                role="option"
189	                aria-selected={propertyScope === null}
190	                onClick={() => {
191	                  setPropFilter(null);
192	                  setScopeOpen(false);
193	                }}
194	              >
195	                all properties
196	              </button>
197	              {addresses.map((a) => (
198	                <button
199	                  key={a}
200	                  type="button"
201	                  className="pc-scope-opt"
202	                  role="option"
203	                  aria-selected={propertyScope === a}
204	                  onClick={() => {
205	                    setPropFilter(a);
206	                    setScopeOpen(false);
207	                  }}
208	                >
209	                  {a}
210	                </button>
211	              ))}
212	            </div>
213	          )}
214	        </div>
215	
216	        <div
217	          className="pc-hero"
218	          role="status"
219	          aria-live="polite"
220	          aria-atomic="true"
221	          aria-label={countAnnouncement}
222	        >
223	          <span className="pc-hero-count">
224	            {tenantsQuery.isLoading ? "—" : scopedTenants.length}
225	          </span>
226	          <span className="pc-hero-label">{countLabel}</span>
227	        </div>
228	
229	        <div className="pc-search-row" data-tutorial-id="property-directory-search">
230	          <div className="pc-search">
231	            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={ACCENT} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5" /><path d="m20 20-3.8-3.8" /></svg>
232	            <input
233	              value={search}
234	              onChange={(e) => setSearch(e.target.value)}
235	              placeholder="search tenants"
236	              aria-label="search tenants"
237	            />
238	          </div>
239	          <button type="button" className="pc-add" data-tutorial-id="property-directory-add" aria-label="add tenant" onClick={() => setAddOpen(true)}>
240	            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth="2.4" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
241	          </button>
242	        </div>
243	
244	        <div className="pc-list">
245	          {tenantsQuery.isLoading ? (
246	            <div className="pc-empty">loading tenants…</div>
247	          ) : rows.length === 0 ? (
248	            <div className="pc-empty">
249	              {term || propertyScope ? "no matching tenants" : "no tenants yet — add your first with +"}
250	            </div>
251	          ) : (
252	            rows.map((t: any) => {
253	              const invoice = invoiceByTenant.get(t.id);
254	              const overdue = invoice?.status === "overdue";
255	              const statusLabel = invoice
256	                ? overdue
257	                  ? `overdue · ${fmtDue(invoice)}`
258	                  : `next payment · ${fmtDue(invoice)}`
259	                : "no invoice yet";
260	              return (
261	                <button
262	                  key={t.id}
263	                  type="button"
264	                  className="pc-row"
265	                  aria-current={t.id === selectedTenantId ? "true" : undefined}
266	                  onClick={() => selectTenant(t.id)}
267	                >
268	                  <span className="pc-avatar">{initialsOf(t)}</span>
269	                  <span className="pc-row-mid">
270	                    <span className="pc-row-name">{fullNameOf(t)}</span>
271	                    <span className="pc-row-status">
272	                      <span
273	                        className="pc-row-dot"
274	                        style={{ background: overdue ? RED : invoice ? ACCENT : AMBER }}
275	                      />
276	                      <span>{statusLabel}</span>
277	                    </span>
278	                  </span>
279	                  <span className="pc-row-address">{t.propertyAddress}</span>
280	                  <span className="pc-row-amt">{invoice ? fmtNZD(invoice.amountCents ?? 0) : "—"}</span>
281	                </button>
282	              );
283	            })
284	          )}
285	        </div>
286	        {selectedTenant && <DesktopDirectoryProfile vertical="property" profile={selectedTenant} />}
287	      </div>
288	
289	      {/* ── add tenant ── */}
290	      {addOpen && (
291	        <div className="pc-modal-wrap">
292	          <div
293	            className="pc-backdrop"
294	            role="button"
295	            tabIndex={-1}
296	            aria-label="close"
297	            onClick={() => setAddOpen(false)}
298	          />
299	          <div className="pc-modal" role="dialog" aria-modal="true" aria-label="add tenant">
300	            <div className="pc-modal-head">
301	              <span className="pc-modal-title">Add tenant</span>
302	              <button type="button" className="pc-modal-x" aria-label="close" onClick={() => setAddOpen(false)}>
303	                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round"><path d="M6 6l12 12M18 6 6 18" /></svg>
304	              </button>
305	            </div>
306	
307	            <div className="pc-grid">
308	              <label className="pc-field">
309	                <span>FIRST NAME</span>
310	                <input value={form.firstName} onChange={(e) => set("firstName")(e.target.value)} aria-label="first name" />
311	              </label>
312	              <label className="pc-field">
313	                <span>LAST NAME</span>
314	                <input value={form.lastName} onChange={(e) => set("lastName")(e.target.value)} aria-label="last name" />
315	              </label>
316	              <label className="pc-field pc-field-wide">
317	                <span>PROPERTY ADDRESS</span>
318	                <input value={form.propertyAddress} onChange={(e) => set("propertyAddress")(e.target.value)} aria-label="property address" />
319	              </label>
320	              <label className="pc-field">
321	                <span>EMAIL</span>
322	                <input value={form.email} onChange={(e) => set("email")(e.target.value)} type="email" aria-label="email" />
323	              </label>
324	              <label className="pc-field">
325	                <span>PHONE</span>
326	                <input value={form.phone} onChange={(e) => set("phone")(e.target.value)} aria-label="phone" />
327	              </label>
328	            </div>
329	
330	            <div className="pc-channel">
331	              <span className="pc-field-label">SEND RENT REQUESTS BY</span>
332	              <div className="pc-channel-chips">
333	                {CHANNELS.map((c) => {
334	                  const on = form.preferredChannel === c.v;
335	                  return (
336	                    <button
337	                      key={c.v}
338	                      type="button"
339	                      className="pc-chip"
340	                      style={{
341	                        border: `1.5px solid ${on ? "transparent" : "rgba(94,158,255,0.5)"}`,
342	                        background: on ? ACTIVE : "transparent",
343	                        color: on ? NAVY : ACCENT_SOFT,
344	                        fontWeight: on ? 700 : 600,
345	                      }}
346	                      onClick={() => setForm((f) => ({ ...f, preferredChannel: c.v }))}
347	                    >
348	                      {c.label}
349	                    </button>
350	                  );
351	                })}
352	              </div>
353	              {!channelContactOk && (
354	                <span className="pc-hint">
355	                  {form.preferredChannel === "email"
356	                    ? "an email address is required to send by email"
357	                    : "a phone number is required to send by sms or whatsapp"}
358	                </span>
359	              )}
360	            </div>
361	
362	            {saveError && <div className="pc-error">{saveError}</div>}
363	
364	            <div className="pc-modal-actions">
365	              <button type="button" className="pc-ghost" onClick={() => setAddOpen(false)}>Cancel</button>
366	              <button
367	                type="button"
368	                className="pc-primary"
369	                disabled={!formValid || createMutation.isPending}
370	                onClick={() => createMutation.mutate(form)}
371	              >
372	                {createMutation.isPending ? "Adding…" : "Add tenant"}
373	              </button>
374	            </div>
375	          </div>
376	        </div>
377	      )}
378	    </DesktopPageScaffold>
379	  );
380	}
381	
382	const PC_CSS = `
383	.pc-body { position:relative; height:100%; box-sizing:border-box; padding:26px 52px 0; }
384	
385	.pc-scope-wrap { position:relative; display:inline-block; z-index:5; }
386	.pc-scope { display:inline-flex; align-items:center; gap:9px; padding:10px 20px; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); background:transparent; font-weight:400; font-size:13.5px; color:${ACCENT_SOFT}; cursor:pointer; transition:background .18s ease; text-transform:lowercase; }
