390	.pc-scope-opt:hover { background:rgba(94,158,255,0.14); }
391	.pc-scope-opt[aria-selected="true"] { background:rgba(94,158,255,0.22); }
392	
393	.pc-hero { margin-top:18px; display:flex; flex-direction:column; animation:popIn .55s cubic-bezier(.34,1.42,.5,1) 40ms both; }
394	.pc-hero-count { font-family:'Outfit',sans-serif; font-weight:700; font-size:96px; line-height:0.95; letter-spacing:-0.01em; color:${ACCENT}; font-variant-numeric:tabular-nums; }
395	.pc-hero-label { margin-top:6px; font-weight:300; font-size:16px; color:${NAV_DIM}; }
396	
397	.pc-search-row { margin-top:56px; display:flex; align-items:center; gap:12px; animation:popIn .55s cubic-bezier(.34,1.42,.5,1) 120ms both; }
398	.pc-search { display:flex; align-items:center; gap:10px; width:300px; height:38px; padding:0 16px; box-sizing:border-box; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); }
399	.pc-search input { flex:1; min-width:0; border:none; background:transparent; outline:none; color:#fff; font-family:'Outfit',sans-serif; font-weight:500; font-size:12px; }
400	.pc-add { width:38px; height:38px; border-radius:50%; background:${ACTIVE}; display:flex; align-items:center; justify-content:center; cursor:pointer; flex:0 0 auto; box-shadow:0 2px 10px rgba(102,169,255,0.35); transition:opacity .15s ease, transform .15s ease; }
401	.pc-add:hover { opacity:0.92; transform:scale(1.05); }
402	
403	.pc-list { margin-top:16px; display:flex; flex-direction:column; gap:5px; width:400px; max-height:520px; overflow-y:auto; scrollbar-width:none; animation:popIn .55s cubic-bezier(.34,1.42,.5,1) 200ms both; }
404	.pc-list::-webkit-scrollbar { display:none; }
405	.pc-row { display:flex; align-items:center; gap:16px; padding:2px 8px 2px 0; border-radius:10px; background:transparent; cursor:pointer; text-align:left; transition:background .15s ease; }
406	.pc-row:hover { background:rgba(94,158,255,0.06); }
407	.pc-row[aria-current="true"] { background:rgba(94,158,255,0.12); }
408	.pc-avatar { width:40px; height:40px; border-radius:50%; border:1.5px solid rgba(94,158,255,0.8); display:flex; align-items:center; justify-content:center; font-weight:700; font-size:11px; color:#fff; flex:0 0 auto; box-sizing:border-box; }
