424	.pc-modal-x { width:32px; height:32px; border-radius:50%; border:1px solid rgba(94,158,255,0.4); display:flex; align-items:center; justify-content:center; background:transparent; cursor:pointer; transition:background .15s ease; }
425	.pc-modal-x:hover { background:rgba(94,158,255,0.1); }
426	
427	.pc-grid { margin-top:20px; display:grid; grid-template-columns:1fr 1fr; gap:12px; }
