429	.pc-field-wide { grid-column:1 / -1; }
430	.pc-field > span, .pc-field-label { font-weight:700; font-size:10px; letter-spacing:0.16em; color:rgba(244,246,255,0.45); }
431	.pc-field input { height:46px; box-sizing:border-box; border-radius:12px; border:1px solid rgba(94,158,255,0.35); background:rgba(94,158,255,0.08); padding:0 16px; font-family:'Outfit',sans-serif; font-weight:600; font-size:13.5px; color:#fff; outline:none; transition:border-color .15s ease; }
432	.pc-field input:focus { border-color:${ACTIVE}; }
