file.content:
  return (
    <DesktopPageScaffold {...props} vertical="property" page="terminal" showScope={false}>
      <style>{PT_CSS}</style>
      <div className="pt-body">
        {/* ── LEFT ── */}
        <div className="pt-left">
          <div>
            <button type="button" className="pt-scope" aria-label="all properties scope" aria-haspopup="listbox">
              <span>all properties</span>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
            </button>
          </div>

          <div className="pt-hero-row">
            <span className="pt-hero">
              {invoicesQuery.isLoading ? "—" : whole(model.outstandingRent)}
            </span>
          </div>
          <span className="pt-hero-sub">outstanding rent</span>
          <span className="pt-hero pt-hero-dim">
            {invoicesQuery.isLoading ? "—" : whole(model.outstandingExpenses)}
          </span>
          <span className="pt-hero-sub pt-hero-sub-dim">outstanding expenses</span>

          <div className="pt-stack">
            <div className="pt-stack-head">
              <span className="pt-stack-title">
                <span>rent request</span>
                <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="m6 14 6-6 6 6" /></svg>
              </span>
              <div className="pt-stack-search">
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={ACCENT} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5" /><path d="m20 20-3.8-3.8" /></svg>
                <input
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="search tenants"
                  aria-label="search requests"
                />
              </div>
            </div>

            <div className="pt-chips">
              {STACK_FILTERS.map((f) => (
                <button key={f} type="button" className="pt-chip" style={chip(f === filter)} onClick={() => setFilter(f)}>
                  {f}
                </button>
              ))}
            </div>

            <div className="pt-rows">
              {invoicesQuery.isLoading ? (
                <div className="pt-empty">loading…</div>
              ) : stackRows.length === 0 ? (
                <div className="pt-empty">no requests here</div>
              ) : (
                stackRows.map((r) => (
                  <div key={r.id} className="pt-row">
                    <span className="pt-avatar">{r.initials}</span>
                    <span className="pt-row-mid">
                      <span className="pt-row-name">{r.name}</span>
                      <span className="pt-row-status">
                        <span className="pt-dot" style={{ background: STATUS_DOT[r.bucket] }} />
                        {r.status}
                      </span>
                    </span>
                    <span className="pt-row-amt">{r.amt}</span>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* ── CENTER RAIL ── */}
        <div className="pt-rail-slot">
          <div className="pt-rail" data-tutorial-id="property-terminal-tools">
            {railBtn("tenant", false, (<><circle cx="12" cy="8" r="3.4" /><path d="M5.5 19.5c1-3.2 3.4-4.8 6.5-4.8s5.5 1.6 6.5 4.8" /></>), "select tenant")}
            {railBtn("request", false, (<><path d="M22 2 11 13" /><path d="M22 2 15 22l-4-9-9-4z" /></>), "rent request")}
            {railBtn("keypad", true, (<path d="M12 5v14M5 12h14" />), "keypad")}
            {railBtn("bill", false, (<><path d="M6 3h12v18l-3-2-3 2-3-2-3 2z" /><path d="M9.5 8h5M9.5 12h5" /></>), "send bill")}
            {railBtn("paid", false, (<><rect x="4" y="4" width="16" height="16" rx="3" /><path d="m9 12 2.2 2.2L15.5 10" /></>), "mark as paid")}
          </div>
        </div>

        {/* ── RIGHT PANEL ── */}
        <div className="pt-panel">
          {mode === "request" && (
            <>
              <div className="pt-mode pt-req-top" data-tutorial-id="property-terminal-request">
                <div className="pt-amt-row">
                  <span className="pt-amt">{fmtNZD(amountCents)}</span>
                  <span className="pt-freq-label">{FREQ_LABEL[frequency]}</span>
                </div>
                <div className="pt-tenant-name">{tenant ? fullNameOf(tenant) : "no tenant selected"}</div>
                <div className="pt-tenant-sub">
                  {tenant ? tenant.propertyAddress : "pick a tenant from the rail"}
                </div>
              </div>

              <div className="pt-req-lower">
                <div className="pt-field-row">
                  <span className="pt-field-strong">{fmtNZD(amountCents)}</span>
                  <span className="pt-field-div">|</span>
                  <span className="pt-field-soft">{FREQ_LABEL[frequency]}</span>
                  <button type="button" className="pt-edit" onClick={openKeypad}>edit&gt;</button>
                </div>

                <div className="pt-field-row">
                  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M20 4H4v12h4v4l5-4h7z" /></svg>
                  <span className="pt-send-via">
                    <span className="pt-send-cap">sending via {channel}</span>
                    <span className="pt-send-to">{channelContact || "no contact on file"}</span>
                  </span>
                </div>

                <div className="pt-freq-chips">
                  {FREQUENCIES.map((f) => (
                    <button key={f} type="button" className="pt-freq-chip" style={chip(f === frequency, 1.5)} onClick={() => setFrequency(f)}>
                      {f}
                    </button>
                  ))}
                </div>

                <button
                  type="button"
                  className="pt-send-btn"
                  data-tutorial-id="property-terminal-send"
                  aria-label="send rent request"
                  disabled={sendRequest.isPending}
                  style={reqFlash ? { borderColor: GREEN, color: GREEN } : undefined}
                  onClick={doSendRequest}
                >
                  {reqLabel}
                </button>
              </div>
            </>
          )}

          {mode === "tenant" && (
            <div className="pt-mode pt-tenants">
              <div className="pt-mode-head">Select Tenant</div>
              <div className="pt-tenant-search">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={ACCENT} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5" /><path d="m20 20-3.8-3.8" /></svg>
                <input
                  value={tenantSearch}
                  onChange={(e) => setTenantSearch(e.target.value)}
                  placeholder="search tenants"
                  aria-label="search tenants"
                />
              </div>
              <div className="pt-tenant-cards">
                {tenantsQuery.isLoading ? (
                  <div className="pt-empty">loading tenants…</div>
                ) : tenantCards.length === 0 ? (
                  <div className="pt-empty">no tenants match</div>
                ) : (
                  tenantCards.map((t: any) => {
                    const next = nextUnpaidFor(t.id);
                    return (
                      <button
                        key={t.id}
                        type="button"
                        className="pt-tenant-card"
                        aria-pressed={t.id === tenantId}
                        style={
                          t.id === tenantId
                            ? { borderColor: ACTIVE, background: "rgba(102,169,255,0.16)" }
                            : undefined
                        }
                        onClick={() => {
                          setTenantId(t.id);
                          if (next?.amountCents) setAmountCents(next.amountCents);
                          setMode("request");
                        }}
                      >
                        <span className="pt-tc-avatar">{initialsOf(t)}</span>
                        <span className="pt-tc-mid">
                          <span className="pt-tc-name">{fullNameOf(t)}</span>
                          <span className="pt-tc-sub">{t.propertyAddress}</span>
                        </span>
                        <span className="pt-tc-right">
                          <span className="pt-tc-amt">{next ? fmtNZD(next.amountCents ?? 0) : "—"}</span>
                          <span className="pt-tc-cap">{next ? "due" : "nothing due"}</span>
                        </span>
                      </button>
                    );
                  })
                )}
              </div>
            </div>
          )}

          {mode === "keypad" && (
            <div className="pt-mode pt-keypad">
              <div className="pt-kp-head">
                <button
                  type="button"
                  className="pt-kp-circle"
                  aria-label="cancel keypad"
                  onClick={() => {
                    setKpVal("");
                    setMode("request");
                  }}
                >
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round"><path d="M6 6l12 12M18 6 6 18" /></svg>
                </button>
                <button
                  type="button"
                  className="pt-kp-circle"
                  aria-label="confirm amount"
                  onClick={() => {
                    setAmountCents(desktopKeypadCents(kpVal));
                    setKpVal("");
                    setMode("request");
                  }}
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12 5 5L19 8" /></svg>
                </button>
              </div>
              <div className="pt-kp-amt">{formatDesktopKeypadMoney(kpVal)}</div>
              <div className="pt-kp-who">
                {tenant ? `${fullNameOf(tenant)} — ${tenant.propertyAddress}` : "no tenant selected"}
              </div>
              <div className="pt-kp-grid">
                {DESKTOP_KEYPAD_KEYS.map((k) => {
                  const fill = k !== "." && k !== "<";
                  return (
                    <DesktopKeypadButton
                      key={k}
                      keyValue={k}
                      className="pt-kp-key"
                      style={{
                        background: fill ? ACTIVE : "transparent",
                        border: fill ? "none" : `1.5px solid ${ACCENT}`,
                        color: fill ? "#FFFFFF" : VIOLET,
                        boxShadow: fill ? "0 14px 22px rgba(0,6,25,0.45)" : "none",
                      }}
                      onPress={pressKey}
                    />
                  );
                })}
              </div>
            </div>
          )}

          {mode === "bill" && (
            <div className="pt-mode pt-bill">
              <div className="pt-amt-row">
                <span className="pt-bill-amt">{fmtNZD(amountCents)}</span>
                <button type="button" className="pt-edit pt-edit-inline" onClick={openKeypad}>edit&gt;</button>
              </div>
              <div className="pt-bill-name">{tenant ? fullNameOf(tenant) : "no tenant selected"}</div>
              <div className="pt-bill-sub">
                {tenant ? tenant.propertyAddress : "pick a tenant from the rail"}
              </div>

              <div className="pt-bill-label">WHAT FOR</div>
              <div className="pt-bill-chips">
                {CHARGE_TYPES.map((c) => {
                  const on = c.id === chargeType;
                  return (
                    <button
                      key={c.id}
                      type="button"
                      className="pt-bill-chip"
                      style={{
                        background: on ? ACTIVE : "rgba(94,158,255,0.12)",
                        color: on ? NAVY : ACCENT_SOFT,
                        fontWeight: on ? 700 : 600,
                      }}
                      onClick={() => {
                        setChargeType(c.id);
                        setDescription(c.preset);
                      }}
                    >
                      {c.label}
                    </button>
                  );
                })}
              </div>

              <div className="pt-bill-label">DESCRIPTION</div>
              <input
                className="pt-bill-input"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="what is this bill for?"
                aria-label="bill description"
              />

              <button
                type="button"
                className="pt-send-btn pt-bill-send"
                aria-label="send bill"
                disabled={sendBill.isPending}
                style={billFlash ? { borderColor: GREEN, color: GREEN } : undefined}
                onClick={doSendBill}
              >
                {billLabel}
              </button>
            </div>
          )}

          {mode === "paid" && (
            <div className="pt-mode pt-paid">
              <div className="pt-mode-head">Mark as paid</div>
              <div className="pt-mode-sub">
                record a payment that arrived outside TaptPay — the tenant stops being chased
              </div>
              <div className="pt-paid-rows">
                {model.rows.filter((r) => r.bucket !== "paid").length === 0 ? (
                  <div className="pt-empty">nothing outstanding</div>
                ) : (
                  model.rows
                    .filter((r) => r.bucket !== "paid")
                    .map((r) => (
                      <div key={r.id} className="pt-paid-row">
                        <span className="pt-paid-mid">
                          <span className="pt-row-name">{r.name}</span>
                          <span className="pt-row-status">{r.status}</span>
                        </span>
                        <span className="pt-row-amt">{r.amt}</span>
                        <button
                          type="button"
                          className="pt-paid-btn"
                          aria-label={`mark ${r.name} paid`}
                          disabled={markPaid.isPending}
                          onClick={() => markPaid.mutate(r.id)}
                        >
                          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={GREEN} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12 5 5L19 8" /></svg>
                        </button>
                      </div>
                    ))
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </DesktopPageScaffold>
  );
}

const PT_CSS = `
.pt-body { position:relative; display:flex; height:100%; box-sizing:border-box; padding:26px 46px 0 52px; }

/* ── left ── */
.pt-left { flex:0 0 420px; display:flex; flex-direction:column; animation:popIn .55s cubic-bezier(.34,1.42,.5,1) 40ms both; }
.pt-scope { display:inline-flex; align-items:center; gap:9px; padding:10px 20px; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); background:transparent; font-weight:400; font-size:13.5px; color:${ACCENT_SOFT}; cursor:pointer; transition:background .18s ease; }
.pt-scope:hover { background:rgba(94,158,255,0.08); }
.pt-hero-row { margin-top:22px; display:flex; align-items:flex-start; gap:14px; }
.pt-hero { font-family:'Outfit',sans-serif; font-weight:700; font-size:84px; line-height:0.92; letter-spacing:-0.015em; color:${ACCENT}; font-variant-numeric:tabular-nums; }
.pt-hero-sub { margin-top:24px; font-weight:300; font-size:17px; color:${NAV_DIM}; }
.pt-hero-dim { margin-top:36px; font-size:56px; opacity:0.61; }
.pt-hero-sub-dim { margin-top:12px; opacity:0.61; }

.pt-stack { margin-top:auto; padding-bottom:24px; }
.pt-stack-head { display:flex; align-items:center; justify-content:space-between; }
.pt-stack-title { display:inline-flex; align-items:center; gap:6px; font-weight:300; font-size:12px; color:${ACCENT_SOFT}; }
.pt-stack-search { display:flex; align-items:center; gap:8px; width:180px; height:32px; padding:0 14px; box-sizing:border-box; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); }
.pt-stack-search input { flex:1; min-width:0; border:none; background:transparent; outline:none; color:#fff; font-family:'Outfit',sans-serif; font-weight:500; font-size:11px; }
.pt-chips { margin-top:12px; display:flex; gap:8px; }
.pt-chip { padding:6px 13px; border-radius:9999px; font-size:11px; cursor:pointer; transition:background .15s ease, color .15s ease; white-space:nowrap; }
.pt-rows { margin-top:8px; display:flex; flex-direction:column; max-height:232px; overflow-y:auto; scrollbar-width:none; }
.pt-rows::-webkit-scrollbar { display:none; }
.pt-row { display:flex; align-items:center; gap:13px; padding:9px 0; }
.pt-avatar { width:40px; height:40px; border-radius:50%; border:1.5px solid rgba(94,158,255,0.8); display:flex; align-items:center; justify-content:center; font-weight:700; font-size:11px; color:#fff; flex:0 0 auto; box-sizing:border-box; }
.pt-row-mid { display:flex; flex-direction:column; gap:2px; flex:1; min-width:0; }
.pt-row-name { font-weight:700; font-size:13px; color:${TEXT_SOFT}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pt-row-status { display:flex; align-items:center; gap:5px; font-weight:500; font-size:10.5px; color:rgba(244,246,255,0.5); }
.pt-dot { width:5px; height:5px; border-radius:50%; opacity:0.85; flex:0 0 auto; }
.pt-row-amt { font-weight:800; font-size:14.5px; color:#fff; font-variant-numeric:tabular-nums; }
.pt-empty { padding:20px 0; font-weight:300; font-size:12.5px; color:rgba(191,209,255,0.5); }

/* ── rail (design pins it at x=550) ── */
.pt-rail-slot { flex:0 0 76px; margin:175px 40px 0 44px; }
.pt-rail { position:absolute; left:550px; width:80px; box-sizing:border-box; border:1.5px solid rgba(94,158,255,0.7); border-radius:32px; padding:30px 0; display:flex; flex-direction:column; align-items:center; gap:40px; }
.pt-rail-btn { width:46px; height:46px; border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer; transition:background .18s ease; }
.pt-rail-btn:hover { background:rgba(94,158,255,0.14); }
.pt-rail-big { width:54px; height:54px; background:${ACTIVE}; box-shadow:0 8px 20px rgba(102,169,255,0.35); }
.pt-rail-big:hover { background:${ACTIVE}; opacity:0.9; }

/* ── right panel ── */
.pt-panel { flex:1; min-width:0; padding-left:36px; box-sizing:border-box; position:relative; }
.pt-mode { animation:tileIn .35s cubic-bezier(.22,.9,.3,1) both; }
.pt-mode-head { font-weight:300; font-size:15px; color:${KP_INK}; }
.pt-mode-sub { margin-top:4px; font-weight:500; font-size:12px; color:rgba(244,246,255,0.45); max-width:430px; }

/* request */
.pt-req-top { position:absolute; top:62px; width:445px; }
.pt-req-lower { position:absolute; top:420px; width:445px; display:flex; flex-direction:column; gap:14px; max-width:430px; }
.pt-amt-row { display:flex; align-items:baseline; gap:12px; }
.pt-amt { font-family:'Outfit',sans-serif; font-weight:700; font-size:66px; line-height:0.95; color:${KP_INK}; font-variant-numeric:tabular-nums; }
.pt-freq-label { font-weight:300; font-size:15px; color:rgba(198,207,226,0.8); }
.pt-tenant-name { margin-top:16px; font-weight:300; font-size:16px; color:${TEXT_SOFT}; }
.pt-tenant-sub { margin-top:4px; font-weight:500; font-size:13px; color:rgba(244,246,255,0.5); }
.pt-field-row { display:flex; align-items:center; gap:14px; height:54px; padding:0 20px; box-sizing:border-box; border-radius:12px; border:1.5px solid rgba(94,158,255,0.55); }
.pt-field-strong { font-weight:600; font-size:14px; color:${TEXT_SOFT}; }
.pt-field-div { color:rgba(94,158,255,0.5); }
.pt-field-soft { font-weight:300; font-size:14px; color:${TEXT_SOFT}; }
.pt-edit { margin-left:auto; font-weight:300; font-size:12px; color:${ACCENT_SOFT}; background:transparent; cursor:pointer; }
.pt-edit-inline { margin-left:0; }
.pt-send-via { display:flex; flex-direction:column; gap:1px; min-width:0; }
.pt-send-cap { font-weight:600; font-size:8.5px; letter-spacing:0.08em; color:rgba(244,246,255,0.45); }
.pt-send-to { font-weight:600; font-size:13px; color:${TEXT_SOFT}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pt-freq-chips { display:flex; gap:10px; margin-top:6px; }
.pt-freq-chip { flex:1; height:44px; border-radius:9999px; font-size:12.5px; cursor:pointer; transition:background .15s ease, color .15s ease; }
.pt-send-btn { margin:44px auto 0; width:200px; height:46px; border-radius:9999px; border:1.5px solid rgba(94,158,255,0.7); background:transparent; font-weight:300; font-size:13.5px; color:${TEXT_SOFT}; cursor:pointer; transition:background .15s ease, border-color .2s ease, color .2s ease; }
.pt-send-btn:hover:not(:disabled) { background:rgba(94,158,255,0.08); }
.pt-send-btn:disabled { opacity:0.55; cursor:default; }

/* tenant picker */
.pt-tenants { padding-top:60px; }
.pt-tenant-search { margin-top:26px; display:flex; align-items:center; gap:10px; width:300px; height:38px; padding:0 16px; box-sizing:border-box; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); }
.pt-tenant-search input { flex:1; min-width:0; border:none; background:transparent; outline:none; color:#fff; font-family:'Outfit',sans-serif; font-weight:500; font-size:12px; }
.pt-tenant-cards { margin-top:26px; display:flex; flex-direction:column; gap:14px; width:440px; max-height:420px; overflow-y:auto; scrollbar-width:none; }
.pt-tenant-cards::-webkit-scrollbar { display:none; }
.pt-tenant-card { display:flex; align-items:center; gap:12px; height:52px; padding:0 12px; box-sizing:border-box; border-radius:10px; border:1.5px solid rgba(94,158,255,0.55); background:rgba(94,158,255,0.07); cursor:pointer; text-align:left; flex:0 0 auto; transition:background .15s ease, border-color .15s ease; }
.pt-tenant-card:hover { background:rgba(94,158,255,0.14); }
.pt-tc-avatar { width:34px; height:34px; border-radius:50%; background:${ACTIVE}; display:flex; align-items:center; justify-content:center; font-weight:700; font-size:10.5px; color:${NAVY}; flex:0 0 auto; }
.pt-tc-mid { display:flex; flex-direction:column; gap:1px; flex:1; min-width:0; }
.pt-tc-name { font-weight:700; font-size:12.5px; color:${TEXT_SOFT}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pt-tc-sub { font-weight:500; font-size:9.5px; color:rgba(244,246,255,0.5); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pt-tc-right { display:flex; flex-direction:column; align-items:flex-end; gap:1px; flex:0 0 auto; }
.pt-tc-amt { font-weight:700; font-size:13px; color:${TEXT_SOFT}; }
.pt-tc-cap { font-weight:500; font-size:9.5px; color:rgba(244,246,255,0.5); }

/* keypad */
.pt-kp-head { display:flex; align-items:center; justify-content:space-between; }
.pt-kp-circle { width:40px; height:40px; border-radius:50%; border:1.5px solid rgba(94,158,255,0.7); display:flex; align-items:center; justify-content:center; background:transparent; cursor:pointer; transition:background .15s ease; }
.pt-kp-circle:hover { background:rgba(94,158,255,0.08); }
.pt-kp-amt { margin-top:10px; text-align:center; font-family:'Outfit',sans-serif; font-weight:700; font-size:68px; line-height:1; color:${KP_INK}; font-variant-numeric:tabular-nums; }
.pt-kp-who { margin-top:84px; text-align:center; font-weight:500; font-size:13px; color:rgba(198,207,226,0.75); }
.pt-kp-grid { margin:30px auto 0; display:grid; grid-template-columns:repeat(3,80px); gap:24px 56px; justify-content:center; }
.pt-kp-key { width:80px; height:80px; border-radius:50%; font-size:34px; font-weight:600; cursor:pointer; display:flex; align-items:center; justify-content:center; font-family:'Outfit',sans-serif; box-sizing:border-box; transition:opacity .12s ease; }
.pt-kp-key:hover { opacity:0.88; }

/* bill */
.pt-bill { margin-top:56px; }
.pt-bill-amt { font-family:'Outfit',sans-serif; font-weight:700; font-size:54px; line-height:0.95; color:${KP_INK}; font-variant-numeric:tabular-nums; }
.pt-bill-name { margin-top:12px; font-weight:300; font-size:15px; color:${TEXT_SOFT}; }
.pt-bill-sub { margin-top:3px; font-weight:500; font-size:12.5px; color:rgba(244,246,255,0.5); }
.pt-bill-label { margin-top:30px; font-weight:700; font-size:10px; letter-spacing:0.18em; color:rgba(244,246,255,0.45); }
.pt-bill-chips { margin-top:12px; display:flex; flex-wrap:wrap; gap:10px; max-width:430px; }
.pt-bill-chip { padding:11px 20px; border-radius:9999px; font-size:12.5px; cursor:pointer; transition:background .15s ease, color .15s ease; }
.pt-bill-input { margin-top:12px; width:430px; height:50px; box-sizing:border-box; border-radius:9999px; border:none; outline:none; background:#fff; padding:0 22px; color:${INK}; font-family:'Outfit',sans-serif; font-weight:600; font-size:14px; }
.pt-bill-send { display:block; margin:34px auto 0; }

/* mark paid */
.pt-paid { margin-top:100px; }
.pt-paid-rows { margin-top:22px; display:flex; flex-direction:column; width:440px; max-height:380px; overflow-y:auto; scrollbar-width:none; }
.pt-paid-rows::-webkit-scrollbar { display:none; }
.pt-paid-row { display:flex; align-items:center; gap:14px; padding:11px 0; border-bottom:1px solid rgba(94,158,255,0.14); }
.pt-paid-mid { display:flex; flex-direction:column; gap:2px; flex:1; min-width:0; }
.pt-paid-btn { width:34px; height:34px; border-radius:50%; border:1.5px solid rgba(53,208,127,0.5); display:flex; align-items:center; justify-content:center; background:transparent; cursor:pointer; flex:0 0 auto; transition:background .15s ease; }
.pt-paid-btn:hover:not(:disabled) { background:rgba(53,208,127,0.12); }
.pt-paid-btn:disabled { opacity:0.5; cursor:default; }
`;

  const generate = () => {
    setReport(pendReport);
    setSheetOpen(false);
    setSheetMode("tiles");
  };

  const sheetTitle =
    sheetMode === "history"
      ? "Payment History"
      : sheetMode === "tiles"
        ? "Reports"
        : PROPERTY_REPORT_BY_ID[pendReport].title;

  const lightChip = (on: boolean) => ({
    border: `1.5px solid ${on ? ACTIVE : "#D6DAE6"}`,
    background: on ? ACTIVE : "transparent",
    color: on ? NAVY : "#5A6480",
    fontWeight: on ? 700 : 600,
  });

  const donutBg = (segs: { pct: number }[]) => {
    let acc = 0;
    const stops = segs.map((s, i) => {
      const part = `${DONUT_COLORS[i % DONUT_COLORS.length]} ${acc}% ${acc + s.pct}%`;
      acc += s.pct;
      return part;
    });
    return `conic-gradient(${stops.join(", ")})`;
  };

  return (
    <DesktopPageScaffold {...props} vertical="property" page="analytics" showScope={false}>
      <style>{PA_CSS}</style>
      <div className="pa-body">
        {/* ── OVERVIEW ── */}
        {!report && (
          <>
            <div className="pa-overview-head">
              <div className="pa-scope-wrap">
                <button
                  type="button"
                  className="pa-scope"
                  aria-label={(scope === ALL_PROPERTIES ? "all properties" : scope) + " scope"}
                  aria-haspopup="listbox"
                  aria-expanded={scopeOpen}
                  onClick={() => setScopeOpen((open) => !open)}
                >
                  <span>{scope === ALL_PROPERTIES ? "all properties" : scope}</span>
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
                </button>
                {scopeOpen && (
                  <div className="pa-scope-menu" role="listbox" aria-label="property scope">
                    {propertyOptions.map((property) => (
                      <button
                        key={property}
                        type="button"
                        role="option"
                        aria-selected={scope === property}
                        className="pa-scope-option"
                        onClick={() => {
                          setScope(property);
                          setScopeOpen(false);
                        }}
                      >
                        {property === ALL_PROPERTIES ? "all properties" : property}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="pa-segs" role="tablist" aria-label="revenue range" data-tutorial-id="pa-period">
                {RANGES.map((range) => {
                  const on = range.k === tf;
                  return (
                    <button
                      key={range.k}
                      type="button"
                      role="tab"
                      aria-selected={on}
                      className="pa-seg"
                      style={{
                        background: on ? ACTIVE : "transparent",
                        color: on ? NAVY : "#6B7BB8",
                        fontWeight: on ? 700 : 600,
                      }}
                      onClick={() => setTf(range.k)}
                    >
                      {range.label}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="pa-hero-row" data-tutorial-id="pa-total">
              <div className="pa-hero-col">
                <div className="pa-hero-amt-row">
                  <span className="pa-hero">{invoicesQuery.isLoading ? "—" : money(overview.total)}</span>
                  {overview.growth !== null && (
                    <span className="pa-hero-pill">
                      {overview.growth >= 0 ? "+" : ""}
                      {overview.growth}%
                    </span>
                  )}
                </div>
                <span className="pa-hero-sub">total revenue</span>
                <span className="pa-hero-out">
                  {invoicesQuery.isLoading ? "—" : money(overview.outstanding)}
                </span>
                <span className="pa-hero-sub pa-hero-sub-dim">outstanding payments</span>
              </div>
            </div>

            <div className="pa-chart">
              <svg className="pa-chart-svg" viewBox="0 0 1076 240" preserveAspectRatio="none" aria-label="collected rent chart">
                <defs>
                  <linearGradient id="proprevfill" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0" stopColor={ACCENT} stopOpacity="0.34" />
                    <stop offset="1" stopColor={ACCENT} stopOpacity="0.02" />
                  </linearGradient>
                </defs>
                <path d={overview.areaD} fill="url(#proprevfill)" />
                <path d={overview.lineD} fill="none" stroke="#8CBBFF" strokeWidth="3" strokeLinecap="round" />
              </svg>
              {overview.peakValue > 0 && (
                <div className="pa-chip" style={{ left: overview.dotLeft }}>
                  {moneyWhole(overview.peakValue)}
                </div>
              )}
            </div>
            {overview.peakValue > 0 && (
              <div
                className="pa-dot"
                style={{ left: overview.floatingDotLeft }}
              />
            )}
          </>
        )}

        {/* ── GENERATED REPORT ── */}
        {report && reportResult && (
          <div className="pa-report">
            <div className="pa-rep-head">
              <button type="button" className="pa-back" onClick={() => setReport(null)}>
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={ACCENT_SOFT} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>
                <span>analytics</span>
              </button>
              <span className="pa-rep-title">{reportResult.title}</span>
              <span className="pa-rep-filter">{((PROPERTY_REPORT_BY_ID[report].periodFiltered ? fPeriod : "Current snapshot") + " · " + fProperty + " · " + fExtra).toLowerCase()}</span>
            </div>

            <div className="pa-rep-body">
              <div className="pa-rep-left">
                <span className="pa-rep-hero">{reportResult.heroV}</span>
                <span className="pa-rep-hero-l">{reportResult.heroL}</span>
                {reportResult.h2V && (
                  <div className="pa-rep-h2">
                    <span className="pa-rep-h2-v">{reportResult.h2V}</span>
                    <span className="pa-rep-h2-l">{reportResult.h2L}</span>
                  </div>
                )}

                {reportResult.chart === "donut" && reportResult.segs.length > 0 && (
                  <div className="pa-donut-row">
                    <div className="pa-donut" style={{ background: donutBg(reportResult.segs) }}>
                      <div className="pa-donut-hole" />
                    </div>
                    <div className="pa-legend">
                      {reportResult.segs.map((sg, i) => (
                        <div key={sg.label} className="pa-legend-row">
                          <span className="pa-legend-dot" style={{ background: DONUT_COLORS[i % DONUT_COLORS.length] }} />
                          <span className="pa-legend-label">{sg.label}</span>
                          <span className="pa-legend-val">{sg.val}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {reportResult.chart === "bars" && reportResult.bars.length > 0 && (
                  <div className="pa-bars">
                    {reportResult.bars.map((b, i) => (
                      <div key={`${b.label}-${i}`} className="pa-bar-col">
                        <div className="pa-bar" style={{ height: `${Math.max(2, Math.round(b.v * 138))}px` }} />
                        <span className="pa-bar-label">{b.label}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="pa-rep-right">
                <span className="pa-rep-detail-title">{reportResult.detailTitle}</span>
                <div className="pa-rep-rows">
                  {reportResult.rows.length === 0 ? (
                    <div className="pa-rep-empty">nothing to report yet</div>
                  ) : (
                    reportResult.rows.map((row, i) => (
                      <div key={`${row.name}-${i}`} className="pa-rep-row">
                        <span className="pa-rep-row-l">
                          <span className="pa-rep-row-name">{row.name}</span>
                          {row.sub && <span className="pa-rep-row-sub">{row.sub}</span>}
                        </span>
                        <span className="pa-rep-row-r">
                          <span className="pa-rep-row-val">{row.val}</span>
                          {row.sub2 && <span className="pa-rep-row-sub2">{row.sub2}</span>}
                        </span>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* ── SHEET ── */}
        <div
          className="pa-sheet"
          data-tutorial-id="pa-history"
          style={{
            transform: `translateY(${sheetY}px)`,
            transition: dragging ? "none" : "transform .5s cubic-bezier(.22,.9,.3,1)",
          }}
        >
          <div
            className="pa-grab"
            role="button"
            tabIndex={0}
            aria-label={sheetOpen ? "collapse payment history" : "expand payment history"}
            aria-expanded={sheetOpen}
            onPointerDown={onSheetDown}
            onPointerMove={onSheetMove}
            onPointerUp={onSheetUp}
            onPointerCancel={onSheetUp}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                setSheetOpen((o) => !o);
              }
            }}
          >
            <span className="pa-grab-bar" />
          </div>

          <div className="pa-sheet-head">
            <span className="pa-sheet-title">{sheetTitle}</span>
            <div className="pa-sheet-actions">
              {sheetMode === "history" && (
                <>
                  <button type="button" className="pa-btn-reports" data-tutorial-id="pa-reports" onClick={openReports}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={DEEP_BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="4" y="4" width="7" height="7" rx="1.5" /><rect x="13" y="4" width="7" height="7" rx="1.5" /><rect x="4" y="13" width="7" height="7" rx="1.5" /><rect x="13" y="13" width="7" height="7" rx="1.5" /></svg>
                    <span>Reports</span>
                  </button>
                  <button type="button" className="pa-btn-white" onClick={() => setExportOpen(true)}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 4v10M8 10l4 4 4-4" /><path d="M5 19h14" /></svg>
                    <span>Export</span>
                  </button>
                </>
              )}
              {sheetMode === "tiles" && (
                <button type="button" className="pa-btn-white" onClick={() => setSheetMode("history")}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>
                  <span>Payment History</span>
                </button>
              )}
              {sheetMode === "filters" && (
                <button type="button" className="pa-btn-white" onClick={() => setSheetMode("tiles")}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>
                  <span>All Reports</span>
                </button>
              )}
            </div>
          </div>

          <div className="pa-sheet-body">
            {sheetMode === "history" &&
              (invoicesQuery.isLoading || tenantsQuery.isLoading ? (
                <div className="pa-sheet-empty">loading payments…</div>
              ) : historyGroups.length === 0 ? (
                <div className="pa-sheet-empty">no payments in this period</div>
              ) : (
                historyGroups.map((group) => (
                  <div key={group.label}>
                    <div className="pa-group-label">{group.label}</div>
                    {group.rows.map((invoice) => {
                      const tenant = tenantById.get(invoice.tenantProfileId);
                      const name =
                        invoice.tenantName?.trim() ||
                        tenantName(tenant) ||
                        "Rent payment";
                      const address =
                        invoice.propertyAddress?.trim() ||
                        tenant?.propertyAddress?.trim() ||
                        "property address unavailable";
                      const splitStatus =
                        invoice.splitCount && invoice.splitCount > 1
                          ? " · " + String(invoice.splitPaidCount ?? 0) + " of " + String(invoice.splitCount) + " shares paid"
                          : "";
                      return (
                        <div key={invoice.id} className="pa-tx-row">
                          <span className="pa-tx-initials">{initials(name)}</span>
                          <span className="pa-tx-mid">
                            <span className="pa-tx-name">{name}</span>
                            <span className="pa-tx-sub">{address}</span>
                          </span>
                          <span className="pa-tx-right">
                            <span className="pa-tx-amt">
                              {money(isPaid(invoice) ? invoiceAmount(invoice) : invoiceOwing(invoice))}
                            </span>
                            <span className="pa-tx-status">
                              {STATUS_LABEL[invoice.status] ?? invoice.status.replace(/_/g, " ")}
                              {splitStatus}
                            </span>
                          </span>
                        </div>
                      );
                    })}
                  </div>
                ))
              ))}

            {sheetMode === "tiles" && (
              <div className="pa-tiles-wrap">
                <div className="pa-tiles-hint">Pick a report to generate — filters come next.</div>
                <div className="pa-tiles">
                  {PROPERTY_DESKTOP_REPORTS.map((r) => (
                    <button key={r.id} type="button" className="pa-tile" onClick={() => pickTile(r.id)}>
                      <span className="pa-tile-ico">
                        <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={DEEP_BLUE} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={r.icon} /></svg>
                      </span>
                      <span className="pa-tile-text">
                        <span className="pa-tile-title">{r.title}</span>
                        <span className="pa-tile-desc">{r.desc}</span>
                      </span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {sheetMode === "filters" && (
              <div className="pa-filters">
                {PROPERTY_REPORT_BY_ID[pendReport].periodFiltered ? (
                  <div className="pa-filter-group">
                    <span className="pa-filter-label">PERIOD</span>
                    <div className="pa-filter-chips">
                      {PROPERTY_PERIOD_CHIPS.map((period) => (
                        <button key={period} type="button" className="pa-fchip" style={lightChip(period === fPeriod)} onClick={() => setFPeriod(period)}>
                          {period}
                        </button>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="pa-filter-group">
                    <span className="pa-filter-label">SNAPSHOT</span>
                    <div className="pa-snapshot-note">This report is a snapshot of your current data.</div>
                  </div>
                )}

                <div className="pa-filter-group">
                  <span className="pa-filter-label">PROPERTY</span>
                  <div className="pa-filter-chips">
                    {propertyOptions.map((v) => (
                      <button key={v} type="button" className="pa-fchip" style={lightChip(v === fProperty)} onClick={() => setFProperty(v)}>
                        {v}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="pa-filter-group">
                  <span className="pa-filter-label">{PROPERTY_REPORT_BY_ID[pendReport].extraLabel}</span>
                  <div className="pa-filter-chips">
                    {PROPERTY_REPORT_BY_ID[pendReport].extra.map((v) => (
                      <button key={v} type="button" className="pa-fchip" style={lightChip(v === fExtra)} onClick={() => setFExtra(v)}>
                        {v}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="pa-generate-row">
                  <button type="button" className="pa-generate" onClick={generate}>Generate Report</button>
                  <span className="pa-generate-note">
                    the top section becomes your report — jump back with the analytics button
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {exportOpen && (
        <ReportModal
          title="Property Reports"
          options={PROPERTY_REPORT_OPTIONS}
          onClose={() => setExportOpen(false)}
          onGenerate={async (id, format, args) => {
            const { runPropertyReport } = await import(
              "@/lib/report-pdf/reports/property"
            );
            await runPropertyReport(id, format, exportData, args.range);
          }}
        />
      )}
    </DesktopPageScaffold>
  );
}

const PA_CSS = `
.pa-body { position:relative; height:100%; box-sizing:border-box; padding:26px 52px 0; overflow:hidden; }

/* ── overview ── */
.pa-overview-head { position:relative; z-index:3; display:flex; align-items:center; justify-content:space-between; }
.pa-scope-wrap { position:relative; }
.pa-scope { display:inline-flex; align-items:center; gap:9px; padding:10px 20px; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); background:transparent; font-weight:400; font-size:13.5px; color:#7FB2FF; cursor:pointer; transition:background .18s ease; }
.pa-scope:hover { background:rgba(94,158,255,0.08); }
.pa-scope-menu { position:absolute; left:0; top:48px; width:280px; box-sizing:border-box; padding:8px; border-radius:16px; border:1px solid rgba(94,158,255,0.3); background:#0F1747; box-shadow:0 18px 45px rgba(0,5,28,0.5); display:flex; flex-direction:column; gap:3px; }
.pa-scope-option { width:100%; padding:10px 12px; border-radius:10px; background:transparent; color:#9DBCFF; text-align:left; font-weight:600; font-size:12.5px; cursor:pointer; }
.pa-scope-option:hover, .pa-scope-option[aria-selected=true] { background:rgba(94,158,255,0.16); color:#FFFFFF; }
.pa-hero-row { position:relative; z-index:1; margin-top:22px; display:flex; align-items:flex-start; justify-content:space-between; }
.pa-hero-col { display:flex; flex-direction:column; gap:6px; }
.pa-hero-amt-row { display:flex; align-items:flex-start; gap:18px; }
.pa-hero { font-family:Outfit,sans-serif; font-weight:700; font-size:63px; line-height:0.92; letter-spacing:-0.015em; color:#5E9EFF; font-variant-numeric:tabular-nums; }
.pa-hero-pill { margin-top:10px; padding:7px 14px; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); font-weight:700; font-size:14px; color:#7FB2FF; white-space:nowrap; }
.pa-hero-sub { font-weight:600; font-size:14px; color:#4A86F0; }
.pa-hero-out { margin-top:26px; font-family:Outfit,sans-serif; font-weight:700; font-size:47px; line-height:0.92; letter-spacing:-0.015em; color:#5E9EFF; opacity:0.61; font-variant-numeric:tabular-nums; }
.pa-hero-sub-dim { font-weight:300; opacity:0.61; }
.pa-segs { display:flex; align-items:center; padding:4px; border-radius:9999px; background:#0F1747; }
.pa-seg { padding:8px 0; width:70px; border-radius:9999px; font-size:12px; cursor:pointer; transition:background .18s ease, color .18s ease; }

.pa-chart { position:relative; margin-top:44px; height:266px; }
.pa-chart-svg { display:block; position:absolute; left:-86px; top:-47px; width:1214px; height:221px; }
.pa-dot { position:absolute; top:185px; width:14px; height:14px; border-radius:50%; background:#FFFFFF; box-shadow:0 0 0 4px rgba(255,255,255,0.18); transform:translate(-50%,-50%); transition:left .3s ease; }
.pa-chip { position:absolute; top:174px; transform:translateX(-50%); padding:7px 14px; border-radius:10px; background:#66A9FF; font-weight:700; font-size:13.5px; color:#000F3F; white-space:nowrap; transition:left .3s ease; }

/* ── generated report ── */
.pa-report { animation:reportIn .55s cubic-bezier(.22,.9,.3,1) both; display:flex; flex-direction:column; height:408px; }
.pa-rep-head { display:flex; align-items:center; gap:14px; }
.pa-back { display:inline-flex; align-items:center; gap:8px; padding:9px 18px; border-radius:9999px; border:1px solid rgba(94,158,255,0.55); background:transparent; font-weight:600; font-size:12.5px; color:${ACCENT_SOFT}; cursor:pointer; transition:background .15s ease; }
.pa-back:hover { background:rgba(94,158,255,0.08); }
.pa-rep-title { font-family:'Outfit',sans-serif; font-weight:700; font-size:24px; color:${TEXT_SOFT}; }
.pa-rep-filter { padding:7px 14px; border-radius:9999px; background:#0F1747; font-weight:600; font-size:11.5px; color:${ACCENT_SOFT}; }
.pa-rep-body { display:flex; gap:56px; margin-top:24px; flex:1; min-height:0; }
.pa-rep-left { flex:0 0 400px; display:flex; flex-direction:column; }
.pa-rep-hero { font-family:'Outfit',sans-serif; font-weight:700; font-size:62px; line-height:0.95; letter-spacing:-0.015em; color:${ACCENT}; }
.pa-rep-hero-l { margin-top:9px; font-weight:300; font-size:14px; color:${NAV_DIM}; }
.pa-rep-h2 { margin-top:14px; display:flex; align-items:baseline; gap:10px; }
.pa-rep-h2-v { font-family:'Outfit',sans-serif; font-weight:700; font-size:27px; color:${ACCENT}; opacity:0.61; }
.pa-rep-h2-l { font-weight:600; font-size:12.5px; color:${NAV_DIM}; opacity:0.61; }
.pa-donut-row { margin-top:26px; display:flex; align-items:center; gap:26px; }
.pa-donut { width:162px; height:162px; border-radius:50%; display:flex; align-items:center; justify-content:center; flex:0 0 auto; }
.pa-donut-hole { width:96px; height:96px; border-radius:50%; background:${NAVY}; }
.pa-legend { display:flex; flex-direction:column; gap:9px; min-width:0; }
.pa-legend-row { display:flex; align-items:center; gap:9px; }
.pa-legend-dot { width:9px; height:9px; border-radius:3px; flex:0 0 auto; }
.pa-legend-label { font-weight:600; font-size:12px; color:rgba(244,246,255,0.7); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:150px; }
.pa-legend-val { font-weight:700; font-size:12px; color:${TEXT_SOFT}; }
.pa-bars { margin-top:26px; display:flex; align-items:flex-end; gap:12px; height:162px; }
.pa-bar-col { flex:1; display:flex; flex-direction:column; align-items:center; justify-content:flex-end; gap:8px; height:100%; }
.pa-bar { width:100%; max-width:44px; border-radius:8px; background:${ACCENT}; animation:tileIn .45s cubic-bezier(.22,.9,.3,1) both; }
.pa-bar-label { font-weight:700; font-size:11.5px; color:${ACCENT_SOFT}; }
.pa-rep-right { flex:1; display:flex; flex-direction:column; min-width:0; }
.pa-rep-detail-title { font-weight:700; font-size:11px; letter-spacing:0.18em; color:${NAV_DIM}; }
.pa-rep-rows { margin-top:4px; display:flex; flex-direction:column; overflow-y:auto; flex:1; scrollbar-width:none; }
.pa-rep-rows::-webkit-scrollbar { display:none; }
.pa-rep-row { display:flex; align-items:center; gap:16px; padding:13px 0; border-bottom:1px solid rgba(94,158,255,0.14); }
.pa-rep-row-l { display:flex; flex-direction:column; gap:2px; flex:1; min-width:0; }
.pa-rep-row-name { font-weight:600; font-size:14px; color:${TEXT_SOFT}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pa-rep-row-sub { font-weight:500; font-size:11.5px; color:rgba(244,246,255,0.45); }
.pa-rep-row-r { display:flex; flex-direction:column; align-items:flex-end; gap:2px; flex:0 0 auto; }
.pa-rep-row-val { font-family:'Outfit',sans-serif; font-weight:700; font-size:15px; color:${ACCENT}; }
.pa-rep-row-sub2 { font-weight:500; font-size:11px; color:rgba(244,246,255,0.4); }
.pa-rep-empty { padding:20px 0; font-weight:300; font-size:12.5px; color:rgba(191,209,255,0.5); }

/* ── payment-history sheet ── */
.pa-sheet { position:absolute; left:0; right:0; bottom:0; height:${SHEET_H}px; border-radius:30px 30px 0 0; background:${SHEET_BG}; box-shadow:0 -18px 50px rgba(3,6,20,0.5); z-index:10; display:flex; flex-direction:column; box-sizing:border-box; }
.pa-grab { flex:0 0 auto; display:flex; align-items:center; justify-content:center; padding:16px 0 8px; cursor:grab; touch-action:none; }
.pa-grab:active { cursor:grabbing; }
.pa-grab-bar { width:66px; height:6px; border-radius:3px; background:#C7CBD8; }
.pa-sheet-head { flex:0 0 auto; display:flex; align-items:center; justify-content:space-between; padding:10px 46px 18px; }
.pa-sheet-title { font-weight:700; font-size:24px; color:${INK}; }
.pa-sheet-actions { display:flex; align-items:center; gap:10px; }
.pa-btn-reports { display:inline-flex; align-items:center; gap:9px; padding:11px 22px; border-radius:9999px; background:transparent; border:1.5px solid ${DEEP_BLUE}; font-weight:700; font-size:14px; color:${DEEP_BLUE}; cursor:pointer; transition:background .15s ease; }
.pa-btn-reports:hover { background:rgba(29,72,200,0.06); }
.pa-btn-white { display:inline-flex; align-items:center; gap:9px; padding:11px 22px; border-radius:9999px; background:#fff; border:1px solid #E2E5EE; font-weight:700; font-size:14px; color:${INK}; cursor:pointer; transition:background .15s ease; }
.pa-btn-white:hover:not(:disabled) { background:#FAFBFD; }
.pa-btn-white:disabled { opacity:0.55; cursor:default; }
.pa-btn-sm { padding:8px 16px; font-size:12.5px; }
.pa-btn-danger { color:#C0343C; border-color:#F0C9CC; }
.pa-sheet-body { flex:1 1 auto; overflow-y:auto; padding:0 46px 26px; }
.pa-sheet-empty { padding:28px 0; font-weight:600; font-size:13px; color:${SHEET_DIM}; }

.pa-group-label { margin-top:24px; font-weight:700; font-size:12px; letter-spacing:0.16em; color:${SHEET_LABEL}; }
.pa-sheet-body > div:first-child > .pa-group-label { margin-top:0; }
.pa-tx-row { width:100%; display:flex; align-items:center; gap:20px; padding:16px 0; border-bottom:1px solid #E6E8F0; background:transparent; cursor:default; text-align:left; }
.pa-tx-initials { width:42px; font-weight:700; font-size:13.5px; color:${SHEET_INK}; flex:0 0 auto; text-transform:uppercase; }
.pa-tx-mid { display:flex; flex-direction:column; gap:3px; flex:1; min-width:0; }
.pa-tx-name { font-weight:700; font-size:15.5px; color:${INK}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.pa-tx-sub { font-weight:500; font-size:12.5px; color:${SHEET_DIM}; }
.pa-tx-right { display:flex; flex-direction:column; align-items:flex-end; gap:3px; flex:0 0 auto; }
.pa-tx-amt { font-weight:700; font-size:15.5px; color:${INK}; font-variant-numeric:tabular-nums; }
.pa-tx-status { font-weight:500; font-size:11.5px; color:${SHEET_LABEL}; }
.pa-tiles-wrap { animation:tileIn .4s cubic-bezier(.22,.9,.3,1) both; }
.pa-tiles-hint { font-weight:600; font-size:13px; color:${SHEET_DIM}; }
.pa-tiles { margin-top:16px; display:grid; grid-template-columns:repeat(5,1fr); gap:10px; }
.pa-tile { display:flex; flex-direction:column; align-items:flex-start; gap:11px; padding:16px; border-radius:14px; background:${SHEET_BG}; border:0; cursor:pointer; text-align:left; transition:background .15s ease; }
.pa-tile:hover { background:#E9EDF6; }
.pa-tile-ico { width:34px; height:34px; border-radius:10px; background:#FFFFFF; box-shadow:0 1px 2px rgba(10,17,40,0.08); display:flex; align-items:center; justify-content:center; flex:0 0 auto; }
.pa-tile-text { display:flex; flex-direction:column; gap:3px; }
.pa-tile-title { font-weight:700; font-size:13.5px; color:${SHEET_INK}; }
.pa-tile-desc { font-weight:500; font-size:11px; line-height:1.35; color:${SHEET_DIM}; }

.pa-filters { animation:tileIn .4s cubic-bezier(.22,.9,.3,1) both; display:flex; flex-direction:column; gap:22px; }
.pa-filter-group { display:flex; flex-direction:column; gap:10px; }
.pa-filter-label { font-weight:700; font-size:11px; letter-spacing:0.16em; color:${SHEET_LABEL}; }
.pa-filter-chips { display:flex; flex-wrap:wrap; gap:8px; }
.pa-fchip { padding:10px 18px; border-radius:9999px; font-size:12.5px; cursor:pointer; transition:background .15s ease, color .15s ease; }
.pa-snapshot-note { width:max-content; max-width:440px; padding:12px 14px; border-radius:12px; background:#FFFFFF; color:${SHEET_DIM}; font-weight:500; font-size:12.5px; }
.pa-generate-row { display:flex; align-items:center; gap:14px; margin-top:4px; }
.pa-generate { height:52px; padding:0 34px; border-radius:9999px; background:${DEEP_BLUE}; color:#fff; font-weight:700; font-size:14.5px; cursor:pointer; transition:opacity .15s ease; }
.pa-generate:hover:not(:disabled) { opacity:0.9; }
.pa-generate:disabled { opacity:0.6; cursor:default; }
.pa-generate-sm { height:42px; padding:0 20px; font-size:13px; }
.pa-generate-note { font-weight:500; font-size:12px; color:#9AA0B4; }

